import{_ as a,o as t,c as i,am as p}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"RabbitMQ的安装与使用","description":"","frontmatter":{"title":"RabbitMQ的安装与使用","excerpt":"RabbitMQ的安装与使用","date":"2023-12-03 23:30:08","updated":"2023-12-03 23:30:08"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/服务安装/RabbitMQ的安装与使用.md","filePath":"部署&工具/Java 知识体系-容器部署/服务安装/RabbitMQ的安装与使用.md","lastUpdated":null}'),s={name:"部署&工具/Java 知识体系-容器部署/服务安装/RabbitMQ的安装与使用.md"};function o(l,e,c,n,d,r){return t(),i("div",null,[...e[0]||(e[0]=[p(`<h3 id="手动部署方式" tabindex="-1">手动部署方式 <a class="header-anchor" href="#手动部署方式" aria-label="Permalink to &quot;手动部署方式&quot;">​</a></h3><h3 id="docker-容器方式" tabindex="-1">Docker 容器方式 <a class="header-anchor" href="#docker-容器方式" aria-label="Permalink to &quot;Docker 容器方式&quot;">​</a></h3><p>1、拉取镜像（默认安装最新版本）</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull rabbitmq</span></span></code></pre></div><p>2、启动RabbitMQ容器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -d --hostname myRabbitMQ --name rabbit -p 5672:5672 -p 15672:15672 rabbitmq</span></span></code></pre></div><p>这个命令的组成部分解释如下：</p><ul><li><code>docker run</code>：启动一个新的容器。</li><li><code>-d</code>：以守护进程模式运行容器，即容器在后台运行。</li><li><code>--hostname myRabbitMQ</code>：为容器设置主机名（<code>myRabbitMQ</code>）。你可以根据需要更改这个值。</li><li><code>--name rabbit</code>：设置容器的名称（<code>rabbit</code>）。这也可以根据你的命名约定来更改。</li><li><code>-p 5672:5672</code>：将容器内部的 5672 端口映射到宿主机的 5672 端口。5672 端口是 RabbitMQ 的默认AMQP端口。</li><li><code>-p 15672:15672</code>：将容器内的 15672 端口映射到宿主机的 15672 端口。15672 端口是 RabbitMQ 管理界面（Management Console）的默认端口。</li><li><code>rabbitmq</code>：指定要使用的 Docker 镜像。</li></ul><p>在 Docker 命令中使用 <code>-p</code> 参数来映射端口时，格式为 <code>-p &lt;宿主机端口&gt;:&lt;容器端口&gt;</code>。</p><p>开放一下端口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>firewall-cmd --permanent --add-port=5672/tcp</span></span>
<span class="line"><span>firewall-cmd --permanent --add-port=15672/tcp</span></span>
<span class="line"><span>firewall-cmd --reload      # 重启防火墙</span></span></code></pre></div><p>访问控制台界面</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://linuxip:15672</span></span></code></pre></div><p>用户名和密码默认都是 guest</p><p>3、开启 Web 界面管控台插件</p><p>对于 Docker 容器中的 RabbitMQ</p><p>如果你是通过 Docker 容器运行 RabbitMQ，并且想要启用管理控制台，通常最简单的方式是直接使用带有管理插件的 RabbitMQ 镜像。例如：</p><p><code>docker run -d --hostname myRabbitMQ --name some-rabbit -p 5672:5672 -p 15672:15672 rabbitmq:3-management</code></p><p>在这个命令中，<code>rabbitmq:3-management</code> 镜像已经包含了管理插件。如果你已经运行了一个不包含管理插件的 RabbitMQ 容器，你可以按照以下步骤启用管理插件：</p><ol><li><p>找出你的 RabbitMQ 容器的 ID 或名称：</p><p><code>docker ps</code></p></li><li><p>进入容器：</p><p><code>docker exec -it [容器ID或名称] bash</code></p></li><li><p>在容器内部，运行以下命令来启用管理插件：</p><p><code>rabbitmq-plugins enable rabbitmq_management</code></p></li><li><p>退出容器：</p><p><code>exit</code></p></li><li><p>重启 RabbitMQ 容器以应用更改。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker restart [容器名称或ID]</span></span></code></pre></div><p>一旦完成，你就可以通过<code>http://linuxip:15672</code></p><p>访问 RabbitMQ 的管理界面。确保你已经将 15672 端口映射到了宿主机上。</p><h3 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h3><hr><p>参考：</p><ul><li><a href="https://blog.csdn.net/u011709538/article/details/131396367" target="_blank" rel="noreferrer">https://blog.csdn.net/u011709538/article/details/131396367</a></li><li><a href="https://zhuanlan.zhihu.com/p/609676322?utm_id=0" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/609676322?utm_id=0</a></li></ul>`,27)])])}const m=a(s,[["render",o]]);export{h as __pageData,m as default};
